Prototypes and the Prototype Chain:
Every object has an internal link to a prototype, and a missing property lookup walks that chain:

```js
const base = { greet() { return `hi ${this.name}`; } };
const user = Object.create(base);
user.name = 'Ana';

console.log(user.greet());                       // 'hi Ana'
console.log(Object.getPrototypeOf(user) === base);   // true
console.log(user.hasOwnProperty('greet'));       // false — inherited
console.log('name' in user);                     // true
```

`new` does four things, and knowing them removes the magic:

```js
function Person(name) {
  this.name = name;
}
Person.prototype.greet = function () { return `hi ${this.name}`; };

const p = new Person('Bo');
console.log(p.greet());                          // 'hi Bo'
console.log(p.constructor === Person);           // true
console.log(p instanceof Person);                // true
console.log(Person.prototype.isPrototypeOf(p));  // true
```

A null prototype is the safe container for data you did not create:

```js
const dict = Object.create(null);
dict['__proto__'] = 'a real key now';
console.log(Object.keys(dict));          // [ '__proto__' ]
console.log(typeof dict.toString);       // 'undefined' — no inherited methods
const normal = {};
normal['__proto__'] = 'ignored';
console.log(Object.keys(normal));        // []
```

Classes and Inheritance:
Class syntax is prototype inheritance with a clearer surface, plus fields and private slots:

```js
class Account {
  owner;                       // public field, initialised per instance
  #balance = 0;                // private, truly inaccessible outside
  static count = 0;

  constructor(owner) {
    this.owner = owner;
    Account.count++;
  }

  deposit(amount) {
    if (amount <= 0) throw new RangeError('amount must be positive');
    this.#balance += amount;
    return this;
  }

  get balance() { return this.#balance; }
  toString() { return `${this.owner}: ${this.#balance}`; }
}

const a = new Account('Ana');
a.deposit(100).deposit(50);
console.log(String(a), Account.count);        // Ana: 150 1
// console.log(a.#balance);                   // SyntaxError outside the class
console.log(Object.keys(a));                  // [ 'owner' ] — #balance is not a key
```

`extends` and `super` link two prototype chains; `super` in the constructor must run before `this`:

```js
class Savings extends Account {
  constructor(owner, rate) {
    super(owner);
    this.rate = rate;
  }
  toString() { return `${super.toString()} @${this.rate}%`; }
}

const s = new Savings('Bo', 3);
s.deposit(200);
console.log(String(s));                       // Bo: 200 @3%
console.log(s instanceof Savings, s instanceof Account);   // true true
```

A mixin is a function that returns a class, which is how you compose behaviour without deep chains:

```js
const Serializable = (Base) => class extends Base {
  toJSON() { return { ...this }; }
};
class Point extends Serializable(Account) {}
console.log(JSON.stringify(new Point('Cy')));   // {"owner":"Cy"}
```

Modules:
Named exports are live bindings, so an importer sees later changes; default exports are a value:

```js
// counter.js
let count = 0;
export function increment() { count += 1; }
export { count };

// main.js
import { count, increment } from './counter.js';
console.log(count);       // 0
increment();
console.log(count);       // 1 — the binding, not a snapshot
```

The shapes you will actually write:

```js
import def from './a.js';                 // default only
import { a, b as bee } from './b.js';     // named, renamed
import def2, { c } from './c.js';         // both
import * as ns from './d.js';             // namespace object
import './setup.js';                      // side effects only

export default function () {}
export const x = 1;
export { x as y };
export * from './e.js';                   // re-export everything
```

Dynamic import returns a promise, which is how you split a bundle or load only when needed:

```js
const mod = await import('./heavy.js');
console.log(mod.default ?? mod);

// in a CommonJS file
async function loadLocale(name) {
  const { messages } = await import(`./locales/${name}.js`);
  return messages;
}
```

ES modules are strict, top-level `await` works, and `this` at the top level is `undefined` — not the global object.

Iterators and Generators:
Any object with a `[Symbol.iterator]` method can be used in `for...of`, spread and destructuring:

```js
class Range {
  constructor(start, end, step = 1) { Object.assign(this, { start, end, step }); }
  *[Symbol.iterator]() {
    for (let i = this.start; i <= this.end; i += this.step) yield i;
  }
}

const r = new Range(1, 5, 2);
console.log([...r]);              // [1, 3, 5]
console.log(Math.max(...r));      // 5
const [first, second] = r;
console.log(first, second);       // 1 3
```

A generator function returns an iterator whose `next()` drives the body, and `yield` is a two-way channel:

```js
function* chat() {
  const name = yield 'what is your name?';
  yield `hello ${name}`;
  return 'done';
}
const it = chat();
console.log(it.next());                 // { value: 'what is your name?', done: false }
console.log(it.next('Ana'));            // { value: 'hello Ana', done: false }
console.log(it.next());                 // { value: 'done', done: true }
```

Because generators are lazy, an infinite one is safe as long as you stop taking:

```js
function* naturals() {
  let n = 0;
  while (true) yield n++;
}
function* take(iterable, n) {
  let i = 0;
  for (const value of iterable) {
    if (i++ >= n) return;
    yield value;
  }
}
console.log([...take(naturals(), 5)]);   // [0, 1, 2, 3, 4]
console.log([...take(naturals(), 3)]);   // [0, 1, 2] — a fresh generator each time
```

Map, Set, WeakMap and WeakSet:
`Map` takes any key and keeps insertion order; object keys are compared by identity:

```js
const m = new Map();
const key = { id: 1 };
m.set(key, 'object key');
m.set(1, 'number key');
m.set(NaN, 'NaN key');
console.log(m.get(key), m.get(NaN), m.size);   // object key NaN key 3
console.log([...m.keys()]);                    // [ { id: 1 }, 1, NaN ]
```

Building set algebra yourself is a few lines, and doing it over arrays instead is quadratic:

```js
const a = new Set([1, 2, 3]);
const b = new Set([3, 4]);
const union = new Set([...a, ...b]);
const intersection = new Set([...a].filter((x) => b.has(x)));
const difference = new Set([...a].filter((x) => !b.has(x)));
console.log([...union], [...intersection], [...difference]);
// [1, 2, 3, 4] [3] [1, 2]
```

`WeakMap` holds keys weakly, which is what makes object metadata safe:

```js
const privateData = new WeakMap();

class Counter {
  constructor() { privateData.set(this, { count: 0 }); }
  inc() { return ++privateData.get(this).count; }
}

let c = new Counter();
c.inc();
console.log(Object.keys(c));        // [] — nothing exposed
c = null;                           // the entry becomes collectable
console.log(privateData.size);      // TypeError: no size — could change any time
```

Regular Expressions:
The difference between `match`, `matchAll` and `exec` trips everyone up:

```js
const text = 'a1 b2 c3';
console.log(text.match(/[a-z]/));         // first match only, with .index
console.log(text.match(/[a-z]/g));        // all matches, no index
console.log([...text.matchAll(/([a-z])(\d)/g)].map((m) => m[2]));   // [ '1', '2', '3' ]
```

Named groups and the replacement function are clearer than numbered captures:

```js
const date = '2024-03-17';
const m = /(?<y>\d{4})-(?<m>\d{2})-(?<d>\d{2})/.exec(date);
console.log(m.groups);                    // { y: '2024', m: '03', d: '17' }

const csv = '1,2,3';
console.log(csv.replace(/(\d)/g, (match, digit) => String(Number(digit) * 2)));   // '2,4,6'
console.log(csv.replace(/(\d)/g, '$1$1'));   // '11,22,33'
console.log('a.b'.replace(/[.]/g, '-'));     // 'a-b' — escape the dot!
```

A global regex carries `lastIndex`, so reusing one on two strings silently skips matches:

```js
const g = /\d/g;
g.exec('12');
console.log(g.lastIndex);        // 1
console.log(g.test('34'));       // true, but starts from index 1

// safe: create a fresh regex per call, or use matchAll / match with g
const count = (s) => [...s.matchAll(/\d/g)].length;
console.log(count('12'), count('34'));   // 2 2
```

The Event Loop:
The order is: synchronous code, then all microtasks, then one macrotask, then all microtasks again:

```js
console.log('script start');

setTimeout(() => console.log('timeout'), 0);

Promise.resolve()
  .then(() => console.log('then 1'))
  .then(() => console.log('then 2'));

queueMicrotask(() => console.log('microtask'));

console.log('script end');

// script start
// script end
// then 1
// microtask
// then 2
// timeout
```

`await` is sugar over a microtask, so it yields the function but not the whole job:

```js
async function f() {
  console.log('f: start');
  await null;
  console.log('f: after await');
}

f();
console.log('sync continues');

// f: start
// sync continues
// f: after await
```

A blocked loop delays timers but not synchronous code, which is why long work must be chunked or moved to a worker:

```js
const spin = (ms) => { const end = Date.now() + ms; while (Date.now() < end); };

const start = Date.now();
setTimeout(() => console.log('timer fired after', Date.now() - start, 'ms'), 10);
spin(100);
console.log('blocked for', Date.now() - start, 'ms');
// blocked for 100 ms
// timer fired after 100 ms — not 10
```

Promises:
Chaining and error handling: a thrown error skips every `then` until a `catch`:

```js
Promise.resolve(1)
  .then((n) => n + 1)
  .then((n) => { throw new Error('boom'); })
  .then(() => console.log('skipped'))
  .catch((err) => { console.log('caught:', err.message); return 99; })
  .finally(() => console.log('always'))
  .then((v) => console.log('recovered with', v));

// caught: boom
// always
// recovered with 99
```

The four combinators fail in different ways, and that difference is the point:

```js
const ok = (v, ms) => new Promise((r) => setTimeout(() => r(v), ms));
const bad = (ms) => new Promise((_, j) => setTimeout(() => j(new Error('nope')), ms));

console.log(await Promise.all([ok(1, 5), ok(2, 1)]));            // [1, 2] — input order
console.log(await Promise.allSettled([ok(1, 5), bad(1)]));
// [ {status:'fulfilled',value:1}, {status:'rejected',reason:Error} ]
console.log(await Promise.any([bad(5), ok('fast', 1)]));         // 'fast'
console.log(await Promise.race([ok('slow', 50), ok('quick', 1)]));   // 'quick'
```

Never construct a promise you cannot reject, and never forget that the executor runs immediately:

```js
const p = new Promise((resolve) => {
  console.log('executor runs now');
  setTimeout(() => resolve('later'), 0);
});
console.log('after construction');
console.log(await p);
// executor runs now
// after construction
// later
```

async and await:
Awaiting in sequence is a correctness tool and a performance trap; the two forms are not equivalent:

```js
const fetchOne = (id) => new Promise((r) => setTimeout(() => r({ id }), 50));

// sequential: ~150ms total
const start1 = Date.now();
const sequential = [];
for (const id of [1, 2, 3]) sequential.push(await fetchOne(id));
console.log('sequential', Date.now() - start1);   // ~150

// parallel: ~50ms total
const start2 = Date.now();
const parallel = await Promise.all([1, 2, 3].map(fetchOne));
console.log('parallel', Date.now() - start2);     // ~50
```

Errors behave like synchronous ones, and `finally` runs either way:

```js
async function load(id) {
  try {
    if (id < 0) throw new RangeError('bad id');
    return await fetchOne(id);
  } catch (err) {
    console.error('load failed:', err.message);
    return null;
  } finally {
    console.log('cleanup for', id);
  }
}
console.log(await load(-1));
```

A floating promise is a bug that never surfaces; `void` marks the ones you mean to ignore:

```js
// bad: an unhandled rejection and no way to know when it finished
function save(data) {
  db.write(data).then(() => console.log('saved'));
}

// good: return it so the caller can await or catch
function saveSafe(data) {
  return db.write(data).then(() => console.log('saved'));
}

// acceptable: deliberately fire and forget, with its own error path
void saveSafe(data).catch((err) => console.error(err));
```

Concurrency, Workers and Cancellation:
`AbortController` is how modern APIs are cancelled, and the signal is passed down rather than checked:

```js
const controller = new AbortController();
const { signal } = controller;

const work = (signal) => new Promise((resolve, reject) => {
  const t = setTimeout(() => resolve('done'), 500);
  signal.addEventListener('abort', () => {
    clearTimeout(t);
    reject(signal.reason);
  });
});

setTimeout(() => controller.abort(new Error('user navigated away')), 50);
try {
  await work(signal);
} catch (err) {
  console.log(err.message);        // user navigated away
}
```

`AbortSignal.timeout` and `AbortSignal.any` remove most of the manual wiring:

```js
const withTimeout = (ms, fn) => fn(AbortSignal.timeout(ms));
try {
  await withTimeout(20, (signal) => work(signal));
} catch (err) {
  console.log(err.name);           // TimeoutError
}

const both = AbortSignal.any([AbortSignal.timeout(1000), controller.signal]);
```

Bounded parallelism is a fixed set of workers draining a shared index, and it is the only way to fan out safely:

```js
async function mapLimit(items, limit, fn) {
  const results = new Array(items.length);
  let next = 0;
  const run = async () => {
    while (next < items.length) {
      const i = next++;
      results[i] = await fn(items[i], i);
    }
  };
  await Promise.all(Array.from({ length: Math.min(limit, items.length) }, run));
  return results;
}

console.log(await mapLimit([1, 2, 3, 4], 2, async (n) => n * n));   // [1, 4, 9, 16]
```
